module sp_ram_lat #(
  parameter  int DW = 32, DEPTH = 1024,
  parameter  int READ_LATENCY = 1,          // 1 or 2
  localparam int AW = $clog2(DEPTH)
) (
  input  logic          clk, en, we,
  input  logic [AW-1:0] addr,
  input  logic [DW-1:0] din,
  output logic [DW-1:0] dout
);
  logic [DW-1:0] mem [DEPTH];
  logic [DW-1:0] q;

  always_ff @(posedge clk)
    if (en) begin
      if (we) mem[addr] <= din;
      q <= mem[addr];
    end

  if (READ_LATENCY == 2) begin : g_oreg
    always_ff @(posedge clk) dout <= q;    // extra output register
  end else begin : g_noreg
    assign dout = q;
  end
endmodule

// read-first
always_ff @(posedge clk)
  if (en) begin
    if (we) mem[addr] <= din;
    dout <= mem[addr];        // old value
  end

// write-first
always_ff @(posedge clk)
  if (en) begin
    if (we) begin
      mem[addr] <= din;
      dout      <= din;       // new value
    end else
      dout <= mem[addr];
  end

// no-change
always_ff @(posedge clk)
  if (en) begin
    if (we) mem[addr] <= din;
    else    dout <= mem[addr]; // only on reads
  end
